// Generator for the Fnatic Streak module device table.
// Usage: node scripts/openrgb/port-fnatic-streak-devices.mjs <openrgb-root> <commit>
// Reads FnaticStreakControllerDetect.cpp / FnaticStreakController.cpp and regenerates
// modules/fnatic-streak/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'FnaticStreakController');
const detect = fs.readFileSync(path.join(family, 'FnaticStreakControllerDetect.cpp'), 'utf8');
const ctrl = fs.readFileSync(path.join(family, 'FnaticStreakController.cpp'), 'utf8');

// LED totals per keyboard type from FnaticStreakController::GetLEDCount
// (mini 106, full 124; the 65 variant is handled by its own packet path).
const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR_I\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*FNATIC_VID\s*,\s*(FNATIC[A-Z0-9_]*_PID)\s*,\s*(\d+)\s*\)/g,
)) {
  const pidDefine = m[3];
  rows.push({
    name: m[1],
    handler: m[2],
    pidDefine,
    interface: Number.parseInt(m[4], 10),
  });
}
if (rows.length === 0) throw new Error('no Fnatic Streak detectors parsed');

const constants = Object.fromEntries(
  [...detect.matchAll(/#define\s+(FNATIC[A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
const vid = constants.FNATIC_VID;
if (vid == null) throw new Error('FNATIC_VID not found');
const protocolOf = (pidDefine) => {
  if (pidDefine.includes('MINISTREAK')) return 'mini';
  if (pidDefine.includes('STREAK65')) return '65';
  return 'full';
};
const ledsOf = (pidDefine) => {
  if (pidDefine.includes('MINISTREAK')) return 106;
  if (pidDefine.includes('STREAK65')) return 65;
  return 124;
};

const out = path.join(process.cwd(), 'modules', 'fnatic-streak', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-fnatic-streak-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, vid: 0x${vid.toString(16).padStart(4, '0')}, pid: 0x${(constants[d.pidDefine] ?? 0).toString(16).padStart(4, '0')}, interface: ${d.interface}, protocol: ${JSON.stringify(protocolOf(d.pidDefine))}, leds: ${ledsOf(d.pidDefine)} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Fnatic Streak HID detectors`);